const rtdal003611Source0005 = `test_that("lsm_l_shdi equals FRAGSTATS", {
    lsm_landscape <- lsm_l_shdi(landscape) |> dplyr::pull(value)
    lsm_augusta <- lsm_l_shdi(augusta_nlcd) |> dplyr::pull(value)

    fs_landscape <- dplyr::filter(fragstats_landscape, LID == "landscape", metric == "shdi") |> dplyr::pull(value)
    fs_augusta <- dplyr::filter(fragstats_landscape, LID == "augusta_nlcd", metric == "shdi") |> dplyr::pull(value)

    expect_true(test_relative(obs = lsm_landscape, exp = fs_landscape, tolerance = tol_rel))
    expect_true(test_relative(obs = lsm_augusta, exp = fs_augusta, tolerance = tol_rel))
})`

