const rtdal003666Source0004 = "axis.default <-\n    function(side = c(\"top\", \"bottom\", \"left\", \"right\"),\n             scales, components, as.table,\n             labels = c(\"default\", \"yes\", \"no\"),\n             ticks = c(\"default\", \"yes\", \"no\"),\n             ...,\n             prefix = lattice.getStatus(\"current.prefix\"))\n{\n    side <- match.arg(side)\n    labels <- match.arg(labels)\n    ticks <- match.arg(ticks)\n    row <- lattice.getStatus(\"current.focus.row\", prefix = prefix)\n    column <- lattice.getStatus(\"current.focus.column\", prefix = prefix)\n    panel.layout <- trellis.currentLayout(\"panel\", prefix = prefix)\n    layout.dim <- dim(panel.layout)\n\n    determineStatus <- function(x)\n    {\n        ## whether the relevant component of 'components' wants us to\n        ## draw something here\n        if (is.null(x) || (is.logical(x) && !x)) FALSE\n        else TRUE\n    }\n    lastPanel <- function()\n    {\n        ## is this the last panel? In that case, it is considered to\n        ## be ``on the boundary'' on the right side.\n        ((pn <- panel.number(prefix = prefix)) > 0 && pn == max(panel.layout))\n    }\n    atBoundary <- function()\n    {\n        switch(side,\n               top = if (as.table) row == 1 else row == layout.dim[1],\n               bottom = if (!as.table) row == 1 else row == layout.dim[1],\n               left = column == 1,\n               right = column == layout.dim[2] || lastPanel())\n    }\n\n    ## FIXME: what about scales$relation ?\n    do.ticks <-\n        switch(ticks,\n               yes = TRUE,\n               no = FALSE,\n               default = scales$draw && determineStatus(components[[side]]) &&\n               (if (scales$relation == \"same\") atBoundary() else TRUE))\n    do.labels <-\n        switch(labels,\n               yes = TRUE,\n               no = FALSE,\n\n               default =\n               scales$draw &&\n               (if (scales$relation == \"same\") {\n\n                   atBoundary() &&\n\n                   ## rule: if (alternating[row/column] %in% c(2, 3)) for\n                   ## a ``boundary'' panel, then draw, otherwise don't.\n                   switch(side,\n                          top    = rep(scales$alternating, length.out = column)[column] %in% c(2, 3),\n                          bottom = rep(scales$alternating, length.out = column)[column] %in% c(1, 3),\n                          left   = rep(scales$alternating, length.out = row)[row] %in% c(1, 3),\n                          right  = rep(scales$alternating, length.out = row)[row] %in% c(2, 3))\n\n               } else TRUE))\n    if (do.ticks || do.labels)\n    {\n        comp.list <-\n            switch(side,\n                   top = if (is.logical(components[[\"top\"]]) && components[[\"top\"]])\n                   components[[\"bottom\"]] else components[[\"top\"]],\n                   bottom = components[[\"bottom\"]],\n                   left = components[[\"left\"]],\n                   right = if (is.logical(components[[\"right\"]]) && components[[\"right\"]])\n                   components[[\"left\"]] else components[[\"right\"]])\n        scales.tck <-\n            switch(side,\n                   left = ,\n                   bottom = scales$tck[1],\n                   right = ,\n                   top = scales$tck[2])\n        if (!is.logical(comp.list)) ## must be FALSE if it is\n        {\n            if (do.ticks)\n                panel.axis(side = side,\n                           at = comp.list$ticks$at,\n                           labels = FALSE,\n                           draw.labels = FALSE, \n                           check.overlap = FALSE,\n                           outside = TRUE,\n                           ticks = TRUE,\n                           tck = scales.tck * comp.list$ticks$tck,\n                           ...)\n            if (do.labels)\n                panel.axis(side = side,\n                           at = comp.list$labels$at,\n                           labels = comp.list$labels$labels,\n                           draw.labels = TRUE, \n                           check.overlap = comp.list$labels$check.overlap,\n                           outside = TRUE,\n                           ticks = FALSE,\n                           tck = scales.tck * comp.list$ticks$tck,\n                           ...)\n        }\n    }\n}"

const rtdal003666Source0005 = `calculateAxisComponents <-
    function(x, ...,
             ## ignored, but needs to be caught:
             packet.number, packet.list, 
             abbreviate = NULL, minlength = 4)

    ## This aims to be a general function which given a general
    ## 'range' x and optional at, generates the locations of tick
    ## marks and corresponding labels. 

    ## x is guaranteed to be given (possibly NA). Possible cases
    ## correspond to factors (character/expression), shingle (see
    ## below), "POSIXt", "date" and usual numeric. The last case will
    ## be default, and will be changed later if necessary.

    ## Theres no need to handle shingles specially. Shingles can also
    ## be thought of as numeric, and thus the default is more
    ## appropriate for functions like xyplot. In functions like
    ## bwplot, things will be adjusted elsewhere when one of the
    ## variables is a shingle.

    ## Note that at and labels will never be TRUE (it's set up that
    ## way), so it's enough to check if they are is.logical(), which
    ## means they are not explicitly specified.

    ## The variables about log scales are required for cases where at
    ## is explicitly specified. In such cases, at will be
    ## log(at,base=logbase), but labels would correspond to at.

{
    if (all(is.na(x)))
        return(list(at = numeric(0),
                    labels = numeric(0),
                    check.overlap = TRUE,
                    num.limit = c(0,1)))

    ## Get ticks and labels depending on x (generic defined below)
    ans <- formattedTicksAndLabels(x, ...)

    ## remove labels outside limits
    rng <- range(ans$num.limit)
    ok <- ans$at >= min(rng) & ans$at <= max(rng)
    ans$at <- ans$at[ok]
    ans$labels <- ans$labels[ok]

    ## abbreviate labels if requested

    if (is.logical(abbreviate) && abbreviate)
        ans$labels <- abbreviate(ans$labels, minlength)

    ans
}`

const rtdal003666Source0006 = `formattedTicksAndLabels <- function(x, ...)
    UseMethod("formattedTicksAndLabels")`

const rtdal003666Source0007 = `formattedTicksAndLabels.default <-
    function(x,
             at = FALSE,
             used.at = NULL,
             labels = FALSE,
             logsc = FALSE,
             ...,
             num.limit = NULL,
             abbreviate = NULL,
             minlength = 4,
             format.posixt = NULL,
             equispaced.log = TRUE)
    ## meant for when x is numeric
{
    rng <-
        if (length(x) == 2) as.numeric(x)
        else range(as.numeric(x))

    ## str(list(x = x, num.limit = num.limit,
    ##          rng = rng, equispaced.log = equispaced.log))

    ## handle log scale (most other methods ignore logsc)
    if (is.logical(logsc) && logsc) logsc <- 10
    have.log <- !is.logical(logsc)

    if (have.log)
        logbase <-
            if (is.numeric(logsc)) logsc
            else if (logsc == "e") exp(1)
            else stop("Invalid value of 'log'")
    logpaste <-
        if (have.log) paste(as.character(logsc), "^", sep = "")
        else ""

    ## will check for overlap only when neither at nor labels is specified

    check.overlap <-
        if (is.logical(at) && is.logical(labels)) TRUE
        else FALSE
        
    if (is.logical(at)) ## at not explicitly specified
    {
        at <-
            if (have.log && !equispaced.log) # FIXME: num.limit instead of rng?
                checkArgsAndCall(axisTicks, list(usr = log10(logbase^rng),
                                                 log = TRUE, axp = NULL, ...))
            else
                checkArgsAndCall(pretty, list(x = x[is.finite(x)], ...))
    }
    else if (have.log && (length(at) > 0))  ## 'at' specified but not NULL
    {
        if (is.logical(labels)) labels <- as.character(at)
        at <- log(at, base = logbase)
    }
    if (is.logical(labels))
    {
        if (have.log && !equispaced.log)
        {
            labels <- as.character(at)
            at <- log(at, logbase)
        }
        else labels <- paste(logpaste, format(at, trim = TRUE), sep = "")
    }
    list(at = at, labels = labels,
         check.overlap = check.overlap,
         num.limit = rng)
}`

const rtdal003666Source0008 = `formattedTicksAndLabels.date <-
    function(x, at = FALSE,
             used.at = NULL,
             ...,
             num.limit = NULL,
             labels = FALSE,
             logsc = FALSE,
             abbreviate = NULL,
             minlength = 4,
             format.posixt = NULL)
{
    ## handle log scales (not very meaningful, though)

    if (is.logical(logsc) && logsc) logsc <- 10
    have.log <- !is.logical(logsc) || logsc

    logbase <-
        if (is.numeric(logsc)) logsc
        else exp(1)


    ## will check for overlap only when neither at nor labels is specified

    check.overlap <-
        if (is.logical(at) && is.logical(labels)) TRUE
        else FALSE
        
    if (is.logical(at)) ## at not explicitly specified
    {
        at <- as.integer(pretty(x[is.finite(x)], ...))
        class(at) <- "date"
        datelabels <- as.character(at)
    }
    else if (have.log && (length(at) > 0))
    {
        if (is.logical(labels)) labels <- as.character(at)
        at <- log(at, base = logbase)
    }
    list(at = at,
         labels = if (is.logical(labels)) datelabels else labels,
         check.overlap = check.overlap,
         num.limit = if (length(x) == 2) as.numeric(x) else as.numeric(range(x)))
}`

const rtdal003666Source0009 = `formattedTicksAndLabels.character <-
    function (x,
              at = FALSE,
              used.at = NULL,
              labels = FALSE,
              logsc = FALSE,
              ...,
              num.limit = NULL,
              abbreviate = NULL,
              minlength = 4,
              format.posixt = NULL)
{
    retain <- if (is.null(used.at) || any(is.na(used.at))) TRUE else used.at
    ## OLD: ans <- list(at = if (is.logical(at)) seq_along(x)[retain] else at,
    ##             labels = if (is.logical(labels)) x[retain] else labels,
    ##             check.overlap = FALSE)
    ans <- list()
    ans$at <- if (is.logical(at)) seq_along(x)[retain] else at
    ans$labels <- if (is.logical(labels)) {
        if (all(ans$at %in% seq_along(x)))
            x[ans$at]
        else ## meaningless at, since not corresponding to values
            as.character(ans$at) # best guess
    } else labels
    ans$check.overlap <- FALSE
    ans$num.limit <-
        c(-1, 1) * lattice.getOption("axis.padding")$factor + 
            if (is.null(num.limit) || any(is.na(num.limit)))
                c(1, length(x)) ## WAS range(ans$at), not sure why
            else num.limit
    ans
}`

