const rtdal003683Source0001 = `panel.refline <- function(...) panel.abline(..., reference = TRUE)`

const rtdal003683Source0002 = `panel.abline <-
    function(a = NULL, b = 0,
             h = NULL,
             v = NULL,
             reg = NULL,
             coef = NULL,
             col,
             col.line = add.line$col,
             lty = add.line$lty,
             lwd = add.line$lwd,
             alpha = add.line$alpha,
             type, ...,
             reference = FALSE,
             identifier = "abline")
{
    add.line <- if (reference) trellis.par.get("reference.line") else trellis.par.get("add.line")
    if (!missing(col) && missing(col.line)) col.line <- col
    ## mostly copied from abline
    if (!is.null(reg))
    {
        if (!is.null(a))
            warning("'a' is overridden by 'reg'")
        a <- reg
    }
    if (is.object(a) || is.list(a))
    {
        p <- length(coefa <- as.vector(coef(a)))
        if (p > 2)
            warning(gettextf("only using the first two of %d regression coefficients", p))
        islm <- inherits(a, "lm")
        noInt <- if (islm)
            !as.logical(attr(stats::terms(a), "intercept"))
        else p == 1
        if (noInt) {
            a <- 0
            b <- coefa[1]
        }
        else {
            a <- coefa[1]
            b <- if (p >= 2)
                coefa[2]
            else 0
        }
    }
    if (!is.null(coef))
    {
        if (!is.null(a))
            warning("'a' and 'b' are overridden by 'coef'")
        a <- coef[1]
        b <- coef[2]
    }
    id <- identifier
    if (hasGroupNumber())
        group <- list(...)$group.number
    else
        group <- 0
    ## draw y = a + bx if appropriate
    if (!is.null(a))
    {
        coeff <- c(a, b)
        cpl <- current.panel.limits()
        xx <- cpl$xlim
        yy <- cpl$ylim

        ## There are six = choose(4, 2) possibilities (plus edge cases):
        ##      I           II           III          IV            V           VI
        ## 4----C----3  4---------3  4---------3  4---------3  4---------3  4---------3
        ## |         |  | /       |  |         |  |  \      |  |     \   |  |         |
        ## |      ---|  |/        |  |         |  |   \     |  |      \  |  |         |
        ## D   ---   B  |         |  |        /|  |    \    |  |       \ |  |         |
        ## |---      |  |         |  |       / |  |     \   |  |        \|  |\        |
        ## |         |  |         |  |      /  |  |      \  |  |         |  | \       |
        ## 1----A----2  1---------2  1---------2  1---------2  1---------2  1---------2

        sign.dist.from.line <- function(x, y)
        {
            as.integer(sign(zapsmall(y - coeff[1] - coeff[2] * x)))
        }
        force(sign.dist.from.line)
        sign.corners <-
            with(cpl,
                 sign.dist.from.line(c(xlim[1], xlim[2], xlim[2], xlim[1]),
                                     c(ylim[1], ylim[1], ylim[2], ylim[2])))
        A <- prod(sign.corners[c(1, 2)]) <= 0
        B <- prod(sign.corners[c(2, 3)]) <= 0
        C <- prod(sign.corners[c(3, 4)]) <= 0
        D <- prod(sign.corners[c(4, 1)]) <= 0

        yfun <- function(x) coeff[1] + coeff[2] * x
        xfun <- function(y) (y - coeff[1]) / coeff[2]
        drawfun <- function(x0, y0, x1, y1, ...)
        {
            panel.segments(x0, y0, x1, y1,
                           col = col.line,
                           lty = lty,
                           lwd = lwd,
                           alpha = alpha,
                           ...,
                           identifier = id)
        }
        ## Do opposite sides first to make sure diagonal edge cases
        ## proceed along the correct branch
        if (D && B) # Case I
            drawfun(xx[1], yfun(xx[1]), xx[2], yfun(xx[2]), ...)
        else if (A && C) # Case IV
            drawfun(xfun(yy[1]), yy[1], xfun(yy[2]), yy[2], ...)
        else if (D && C) # Case II
            drawfun(xx[1], yfun(xx[1]), xfun(yy[2]), yy[2], ...)
        else if (A && B) # Case III
            drawfun(xfun(yy[1]), yy[1], xx[2], yfun(xx[2]), ...)
        else if (B && C) # Case  V
            drawfun(xfun(yy[1]), yy[1], xfun(yy[2]), yy[2], ...)
        else if (A && D) # Case VI
            drawfun(xx[1], yfun(xx[1]), xfun(yy[1]), yy[1], ...)
    }
    if (length(h <- as.numeric(h)) > 0)
        grid.segments(y0 = h, y1 = h, default.units="native",
                      name = trellis.grobname(paste(identifier, "h", sep="."),
                        type = "panel", group = group),
                      gp = gpar(col = col.line, lty = lty,
                                lwd = lwd, alpha = alpha))
    if (length(as.numeric(v)) > 0)
        grid.segments(x0 = v, x1 = v, default.units="native",
                      name = trellis.grobname(paste(identifier, "v", sep="."),
                        type = "panel", group = group),
                      gp = gpar(col = col.line, lty = lty,
                                lwd = lwd, alpha = alpha))
    invisible()
}`

const rtdal003683Source0003 = `panel.curve <-
    function (expr, from, to, n = 101,
              curve.type = "l",
              col = add.line$col,
              lty = add.line$lty,
              lwd = add.line$lwd,
              type, ## ignored, to avoid type meant for panel.xyplot etc
              ...,
              identifier = "curve")
    ## curve has a log option. Unfortunately there is no easy way to
    ## read in the lattice log options (specified via scales) into the
    ## panel function. Maybe some day if grid natively supports log
    ## scales and lattice is redesigned to take advantage of that
{
    add.line <- trellis.par.get("add.line")
    sexpr <- substitute(expr)
    if (is.name(sexpr))
    {
        fcall <- paste(sexpr, "(x)")
        expr <- parse(text = fcall)
    }
    else
    {
        if (!(is.call(sexpr) && match("x", all.vars(sexpr), nomatch = 0)))
            stop("'expr' must be a function or an expression containing 'x'")
        expr <- sexpr
    }
    lims <- current.panel.limits()$xlim
    if (missing(from)) from <- min(lims)
    if (missing(to)) to <- max(lims)
    x <- seq(from, to, length.out = n)
    y <- eval(expr, envir = list(x = x), enclos = parent.frame())
    if (hasGroupNumber())
        id <- paste(identifier, "group", list(...)$group.number, sep=".")
    else
        id <- identifier
    panel.lines(x, y, type = curve.type, col = col, lty = lty, lwd = lwd, ...,
                identifier = id)
}`

const rtdal003683Source0004 = `panel.rug <-
    function(x = NULL, y = NULL,
             regular = TRUE,
             start = if (regular) 0 else 0.97,
             end = if (regular) 0.03 else 1,
             x.units = rep("npc", 2),
             y.units = rep("npc", 2),
             col = plot.line$col,
             col.line = col,
             lty = plot.line$lty,
             lwd = plot.line$lwd,
             alpha = plot.line$alpha,
             ...,
             identifier = "rug")
{
    if (!any(is.finite(x))) x <- NULL
    if (!any(is.finite(y))) y <- NULL
    plot.line <- trellis.par.get("plot.line")
    x.units <- rep(x.units, length.out = 2)
    y.units <- rep(y.units, length.out = 2)
    id <- identifier
    if (hasGroupNumber())
        group <- list(...)$group.number
    else
        group <- 0
    if (!is.null(x))
    {
        grid.segments(x0 = unit(x, "native"), x1 = unit(x, "native"),
                      y0 = unit(start, x.units[1]), y1 = unit(end, x.units[2]),
                      name = trellis.grobname(paste(id, "x", sep="."),
                        type = "panel", group = group),
                      gp =
                      gpar(col = col.line, lty = lty,
                           lwd = lwd, alpha = alpha))
    }
    if (!is.null(y))
    {
        grid.segments(y0 = unit(y, "native"), y1 = unit(y, "native"),
                      x0 = unit(start, y.units[1]), x1 = unit(end, y.units[2]),
                      name = trellis.grobname(paste(id, "y", sep="."),
                        type = "panel", group = group),
                      gp =
                      gpar(col = col.line, lty = lty,
                           lwd = lwd, alpha = alpha))
    }
}`

const rtdal003683Source0005 = `panel.fill <-
    function(col = trellis.par.get("background")$col,
             border = "transparent", ...,
             identifier = "fill")
{
    if (hasGroupNumber())
        group <- list(...)$group.number
    else
        group <- 0
    grid.rect(name = trellis.grobname(identifier,
                type = "panel", group = group),
              gp =
              gpar(fill = col,
                   col = border,
                   ...))
}`

const rtdal003683Source0006 = "panel.grid <-\n    function(h = 3, v = 3,\n             col,\n             col.line = reference.line$col,\n             lty = reference.line$lty,\n             lwd = reference.line$lwd,\n             x = NULL, y = NULL, ...,\n             identifier = \"grid\")\n{\n    reference.line <- trellis.par.get(\"reference.line\")\n    if (!missing(col) && missing(col.line)) col.line <- col\n    h <- as.integer(h)\n    v <- as.integer(v)\n\n    if (hasGroupNumber())\n        group <- list(...)$group.number\n    else\n        group <- 0\n    if (h > 0)\n        grid.segments(y0 = 1:h / (h+1),\n                      y1 = 1:h / (h+1),\n                      gp = gpar(col = col.line, lty = lty, lwd = lwd),\n                      default.units = \"npc\",\n                      name = trellis.grobname(paste(identifier, \"h\", sep=\".\"),\n                        type = \"panel\", group = group))\n\n    if (v > 0)\n        grid.segments(x0 = 1:v / (v+1),\n                      x1 = 1:v / (v+1),\n                      gp = gpar(col = col.line, lty = lty, lwd = lwd),\n                      default.units = \"npc\",\n                      name = trellis.grobname(paste(identifier, \"v\", sep=\".\"),\n                        type = \"panel\", group = group))\n\n    ## Cheating here a bit for h=-1, v=-1. Can't think of any neat way to\n    ## get the actual `at' values of the panel\n\n    limits <- current.panel.limits()\n\n    if (h < 0)\n    {\n        if (h == -1) n <- 5 else n <- -h\n        scale <- limits$ylim\n        if (!is.null(y)) {\n            ## class() <- \"factor\" is an error\n            if (inherits(y, \"factor\"))\n                y <- as.character(y)\n            mostattributes(scale) <- attributes(y)\n        }\n        ## at <- pretty(scale, n = n)\n        at <- formattedTicksAndLabels(scale, n = n)$at\n        at <- at[at > min(scale) & at < max(scale)]\n        grid.segments(y0 = at,\n                      y1 = at,\n                      gp = gpar(col = col.line, lty = lty, lwd = lwd),\n                      default.units = \"native\",\n                      name = trellis.grobname(paste(identifier, \"h\", sep=\".\"),\n                        type = \"panel\", group = group))\n    }\n    if (v < 0)\n    {\n        if (v == -1) n <- 5 else n <- -v\n        scale <- limits$xlim\n        if (!is.null(x)) {\n            ## class() <- \"factor\" is an error\n            if (inherits(x, \"factor\"))\n                x <- as.character(y)\n            mostattributes(scale) <- attributes(x)\n        }\n        ## at <- pretty(scale, n = n)\n        at <- formattedTicksAndLabels(scale, n = n)$at\n        at <- at[at > min(scale) & at < max(scale)]\n        grid.segments(x0 = at,\n                      x1 = at,\n                      gp = gpar(col = col.line, lty = lty, lwd = lwd),\n                      default.units = \"native\",\n                      name = trellis.grobname(paste(identifier, \"v\", sep=\".\"),\n                        type = \"panel\", group = group))\n    }\n}"

const rtdal003683Source0007 = `panel.lmline <-
    function(x, y, ...,
             identifier = "lmline")
{
    if (length(x) > 1)
        panel.abline(lm(as.numeric(y) ~ as.numeric(x)), ...,
                     identifier = identifier)
}`

const rtdal003683Source0008 = `prepanel.lmline <-
    function(x, y, ...)
{
    x <- as.numeric(x)
    y <- as.numeric(y)

    if (length(x) > 1) {
        coeff <- coef(lm(y~x))
        tem <- coeff[1] + coeff[2] * range(x, finite = TRUE)
        list(xlim = range(x, finite = TRUE),
             ylim = range(y, tem, finite = TRUE),
             dx = diff(range(x, finite = TRUE)),
             dy = diff(tem, finite = TRUE))
    }
    else prepanel.null()
}`

const rtdal003683Source0009 = `panel.linejoin <-
panel.average <-
    function(x, y, fun = mean,
             horizontal = TRUE,
             lwd = reference.line$lwd,
             lty = reference.line$lty,
             col,
             col.line = reference.line$col,
             type = "l", ## ignored
             ...,
             identifier = "linejoin")
{
    ## FIXME: pretty sure this can be made more readable using tapply (or aggregate)
    x <- as.numeric(x)
    y <- as.numeric(y)

    reference.line = trellis.par.get("reference.line")
    if (!missing(col))
    {
        if (missing(col.line)) col.line <- col
    }
    if (horizontal)
    {
        vals <- unique(sort(y))
        yy <- seq_along(vals)
        xx <- numeric(length(yy))
        for (i in yy)
            xx[i] <- fun(x[y == vals[i]])
        panel.lines(xx, vals[yy], col = col.line, lty = lty, lwd = lwd, ...,
                    identifier = identifier)
    }
    else
    {
        vals <- unique(sort(x))
        xx <- seq_along(vals)
        yy <- numeric(length(xx))
        for (i in xx)
            yy[i] <- fun(y[x == vals[i]])
        panel.lines(vals[xx], yy, col = col.line, lty = lty, lwd = lwd, ...,
                    identifier = identifier)
     }
}`

const rtdal003683Source0010 = `panel.mathdensity <-
    function(dmath = dnorm,
             args = list(mean = 0, sd = 1),
             n = 50,
             col,
             col.line = reference.line$col,
             lwd = reference.line$lwd,
             lty = reference.line$lty,
             type,
             ...,
             identifier = "mathdensity")
{
    reference.line <- trellis.par.get("reference.line")
    if (!missing(col) && missing(col.line)) col.line <- col
    x <- do.breaks(endpoints = current.panel.limits()$xlim, nint = n)
    y <- do.call("dmath", c(list(x = x), args))
    panel.lines(x = x, y = y, col = col.line, lwd = lwd, lty = lty, ...,
                identifier = identifier)
}`

