const rtdal003694Source0001 = `summary.trellis <-
    function(object, ...)
{
    ans <- 
        with(object,
             list(call = call,
                  packet.sizes = packet.sizes,
                  index.cond = index.cond,
                  perm.cond = perm.cond))
    class(ans) <- "summary.trellis"
    ans
}`

const rtdal003694Source0002 = `print.summary.trellis <- function(x, ...)
{
    cat(gettext("\nCall:\n"))
    print(x$call)
    cat(gettext("\nNumber of observations:\n"))
    ps <-
        do.call("[",
                c(list(x$packet.sizes),
                  x$index.cond,
                  list(drop = FALSE)))
    if (!is.null(dim(ps)))
        ps <- aperm(ps, x$perm.cond)
    print(ps)
    invisible(x)
}`

const rtdal003694Source0005 = `"dimnames<-.trellis" <- 
    function (x, value)
{
    d <- dim(x)
    if (!is.list(value) || length(value) != length(d))
        stop("supplied 'dimnames' have wrong length")
    if (!all(d == sapply(value, length)))
        stop("some components of supplied 'dimnames' have wrong length")
    x$condlevels <- value
    x
}`

