const rtdal003771Source0007 = `base64local <- function(img) {
  if (file.exists(img)) {
    fileext <- tools::file_ext(img)
    if (fileext == "svg") fileext <- paste0(fileext, "+xml")
    img <- base64enc::dataURI(file = img, mime = paste0("image/", fileext))
  }
  img
}`

