const rtdal003773Source0001 = `addPMPolygons = function(
    map
    , url
    , style
    , layerId = NULL
    , group = NULL
    , pane = "overlayPane"
    , attribution = NULL
) {

  if (length(style) == 0) {
    stop(
      "need at least one paint rule set to know which layer to visualise"
      , call. = FALSE
    )
  }

  map$dependencies <- c(
    map$dependencies
    , leafletPMTilesDependencies()
    , fgbDependencies()
    , chromaJsDependencies()
  )

  leaflet::invokeMethod(
    map
    , data = leaflet::getMapData(map)
    , method = "addPMPolygons"
    # , paste0(path_layer, "/", basename(file))
    , url
    , layerId
    , group
    , style
    , pane
    , attribution
  )
}`

