const rtdal003778Source0001 = `glifyDependencies = function(src = FALSE) {
  src <- ifelse(src, "Src", "")
  list(
    htmltools::htmlDependency(
      "Leaflet.glify",
      '3.3.1',
      system.file("htmlwidgets/Leaflet.glify", package = "leafgl"),
      script = c(
        "GlifyUtils.js"
        , paste0("addGlifyPoints", src, ".js")
        , paste0("addGlifyPolygons", src, ".js")
        , paste0("addGlifyPolylines", src, ".js")
        , "glify-browser.js"
      )
    )
  )
}`

const rtdal003778Source0002 = `glifyDataAttachmentSrc = function(fl_data, group, async = FALSE) {
  data_dir <- dirname(fl_data)
  data_file <- basename(fl_data)
  if (async) {
    list(
      htmltools::htmlDependency(
        name = paste0("pts_2", "dat"),
        version = 1,
        src = "",
        head = paste0('<script src="lib/', paste0(group, 'dat-1/'), data_file, '" async></script>')
      )
    )
  } else {
    list(
      htmltools::htmlDependency(
        name = paste0(group, "dat"),
        version = 1,
        src = c(file = data_dir),
        script = list(data_file)
      )
    )
  }
}`

const rtdal003778Source0003 = `glifyAttachmentSrc <- function(fl, group, type) {
  valid_types <- c("col", "pop", "lab", "rad")
  if (!type %in% valid_types) {
    stop("Invalid type. Valid types are: col, pop, lab, rad.")
  }
  data_dir <- dirname(fl)
  data_file <- basename(fl)
  list(
    htmltools::htmlDependency(
      name = paste0(group, type),
      version = 1,
      src = c(file = data_dir),
      script = list(data_file)
    )
  )
}`

const rtdal003778Source0004 = `yyson_json_str <- function(x, ...) {
  dt <- yyjsonr::write_json_str(x, ...)
  class(dt) <- "json"
  dt
}`

const rtdal003778Source0005 = `yyson_geojson_str <- function(x, ...) {
  dt <- yyjsonr::write_geojson_str(x, ...)
  class(dt) <- "json"
  dt
}`

