const rtdal003809Source0001 = "evalFormula <- function(list, data) {\n  evalAll <- function(x) {\n    if (is.list(x)) {\n      # Use `x[] <-` so attributes on x are preserved\n      x[] <- lapply(x, evalAll)\n      x\n    } else {\n      resolveFormula(x, data)\n    }\n  }\n  evalAll(list)\n}"

const rtdal003809Source0002 = `expandLimits <- function(map, lat, lng) {
  if (is.null(map$x$limits)) {
    map$x$limits <- list()
  }

  # We remove NA's and check the lengths so we never call range() with an empty
  # set of arguments (or all NA's), which will cause a warning.

  lat <- lat[is.finite(lat)]
  lng <- lng[is.finite(lng)]

  if (length(lat) > 0) {
    map$x$limits$lat <- range(map$x$limits$lat, lat)
  }
  if (length(lng) > 0) {
    map$x$limits$lng <- range(map$x$limits$lng, lng)
  }

  map
}`

const rtdal003809Source0004 = `bboxNull <- cbind(min = c(x = Inf, y = Inf), max = c(x = -Inf, y = -Inf))`

const rtdal003809Source0013 = `addRasterImage <- function(
  map,
  x,
  colors = if (is.factor(x)[1]) "Set1" else "Spectral",
  opacity = 1,
  attribution = NULL,
  layerId = NULL,
  group = NULL,
  project = TRUE,
  method = c("auto", "bilinear", "ngb"),
  maxBytes = 4 * 1024 * 1024,
  options = gridOptions(),
  data = getMapData(map)
) {
  if (inherits(x, "SpatRaster")) {
    addRasterImage_SpatRaster(
      map = map,
      x = x,
      colors = colors,
      opacity = opacity,
      attribution = attribution,
      layerId = layerId,
      group = group,
      project = project,
      method = method,
      maxBytes = maxBytes,
      options = options,
      data = data
    )
  } else if (inherits(x, "RasterLayer")) {
    addRasterImage_RasterLayer(
      map = map,
      x = x,
      colors = colors,
      opacity = opacity,
      attribution = attribution,
      layerId = layerId,
      group = group,
      project = project,
      method = method,
      maxBytes = maxBytes,
      options = options,
      data = data
    )
  } else {
    stop("Don't know how to get path data from object of class ", class(x)[[1]])
  }
}`

const rtdal003809Source0014 = "addRasterLegend <- function(map, x, layer = 1, ...) {\n  stopifnot(inherits(x, \"SpatRaster\"))\n  stopifnot(length(layer) == 1 && layer > 0 && layer <= terra::nlyr(x))\n\n  # might as well do this here and only once. Subsetting would otherwise have\n  # been necessary in\n  # color_info <- base::subset(color_info, value %in% terra::values(x))\n  x <- x[[layer]]\n\n  # Retrieve the color table from the layer. If one doesn't exist, that means\n  # the raster was colored some other way, like using colorFactor or something,\n  # and the regular addLegend() is designed for those cases.\n  ct <- terra::coltab(x)[[1]]\n  if (is.null(ct)) {\n    stop(\n      \"addRasterLegend() can only be used on layers with color tables (see ?terra::coltab). Otherwise, use addLegend().\"\n    )\n  }\n\n  # Create a data frame that has value and color columns\n  # Extract the colors in #RRGGBBAA format\n  color_info <- data.frame(\n    value = ct[[1]],\n    color = grDevices::rgb(\n      ct$red / 255,\n      ct$green / 255,\n      ct$blue / 255,\n      ct$alpha / 255\n    )\n  )\n\n  lvls <- terra::levels(x)[[1]]\n\n  # Drop values that aren't part of the layer unlike \"values\",  \"unique\" is\n  # memory-safe; it does not load all values into memory if the raster is large.\n  # So instead of:\n  #\n  #  color_info <- base::subset(color_info, value %in% terra::values(x))\n  #\n  # remove the levels to get the raw cell values\n  levels(x) <- NULL\n  value_in_layer <- color_info$value %in% terra::unique(x)[[1]]\n  color_info <- color_info[value_in_layer & !is.na(value_in_layer), ]\n\n  res <- if (is.data.frame(lvls)) {\n    # Use the labels from levels(x), and look up the matching colors.\n    # The levels data frame can have varying colnames, just normalize them\n    colnames(lvls) <- c(\"value\", \"label\")\n    base::merge(color_info, lvls, by.x = \"value\", by.y = 1)\n  } else {\n    # No level labels provided; use the values as labels\n    cbind(color_info, label = color_info$value)\n  }\n\n  # At this point, res is a data frame with `value`, `color`, and `label` cols,\n  # and values/colors not present in the raster layer have been dropped\n\n  addLegend(map, colors = res[[\"color\"]], labels = res[[\"label\"]], ...)\n}"

const rtdal003809Source0015 = `addRasterImage_RasterLayer <- function(
  map,
  x,
  colors = if (is.factor(x)[1]) "Set1" else "Spectral",
  opacity = 1,
  attribution = NULL,
  layerId = NULL,
  group = NULL,
  project = TRUE,
  method = c("auto", "bilinear", "ngb"),
  maxBytes = 4 * 1024 * 1024,
  options = gridOptions(),
  data = getMapData(map)
) {
  options$opacity <- opacity
  options$attribution <- attribution

  raster_is_factor <- raster::is.factor(x)
  method <- match.arg(method)
  if (method == "auto") {
    if (raster_is_factor) {
      method <- "ngb"
    } else {
      method <- "bilinear"
    }
  }

  if (project) {
    # if we should project the data
    projected <- projectRasterForLeaflet(x, method)
  } else {
    # do not project data
    projected <- x
  }

  bounds <- raster::extent(
    raster::projectExtent(
      raster::projectExtent(x, crs = sp::CRS(epsg3857)),
      crs = sp::CRS(epsg4326)
    )
  )

  if (!is.function(colors)) {
    if (method == "ngb") {
      # 'factors'
      colors <- colorFactor(
        colors,
        domain = NULL,
        na.color = "#00000000",
        alpha = TRUE
      )
    } else {
      # 'numeric'
      colors <- colorNumeric(
        colors,
        domain = NULL,
        na.color = "#00000000",
        alpha = TRUE
      )
    }
  }

  tileData <- raster::values(projected) %>%
    colors() %>%
    col2rgb(alpha = TRUE) %>%
    as.raw()
  dim(tileData) <- c(4, ncol(projected), nrow(projected))
  pngData <- png::writePNG(tileData)
  if (length(pngData) > maxBytes) {
    stop(
      "Raster image too large; ",
      length(pngData),
      " bytes is greater than maximum ",
      maxBytes,
      " bytes"
    )
  }
  uri <- xfun::base64_uri(pngData, "image/png")

  latlng <- list(
    list(raster::ymax(bounds), raster::xmin(bounds)),
    list(raster::ymin(bounds), raster::xmax(bounds))
  )

  invokeMethod(
    map,
    data,
    "addRasterImage",
    uri,
    latlng,
    layerId,
    group,
    options
  ) %>%
    expandLimits(
      c(raster::ymin(bounds), raster::ymax(bounds)),
      c(raster::xmin(bounds), raster::xmax(bounds))
    )
}`

const rtdal003809Source0016 = `addRasterImage_SpatRaster <- function(
  map,
  x,
  colors = if (terra::is.factor(x)[1]) "Set1" else "Spectral",
  opacity = 1,
  attribution = NULL,
  layerId = NULL,
  group = NULL,
  project = TRUE,
  method = c("auto", "bilinear", "ngb"),
  maxBytes = 4 * 1024 * 1024,
  options = gridOptions(),
  data = getMapData(map)
) {
  rlang::check_installed(
    "terra (>= 1.6-3)",
    reason = "to use addRasterImage() for SpatRaster objects."
  ) # for terra::has.RGB()

  options$opacity <- opacity
  options$attribution <- attribution

  if (terra::has.RGB(x)) {
    # RGB(A) channels to color table
    x <- terra::colorize(x, "col")
  } else if (terra::nlyr(x) > 1) {
    x <- x[[1]]
    warning("using the first layer in 'x'", call. = FALSE)
  }

  raster_is_factor <- terra::is.factor(x)

  # there 1.5-50 has terra::has.colors(x)
  ctab <- terra::coltab(x)[[1]]
  has_colors <- !is.null(ctab)

  method <- match.arg(method)
  if (method == "ngb") {
    method = "near"
  }
  if (method == "auto") {
    if (raster_is_factor || has_colors) {
      method <- "near"
    } else {
      method <- "bilinear"
    }
  }

  bounds <- terra::ext(
    terra::project(
      terra::project(
        terra::as.points(terra::ext(x), crs = terra::crs(x)),
        epsg3857
      ),
      epsg4326
    )
  )
  ## can't the above be simplified to this?
  #  bounds <- terra::ext(
  #    terra::project(
  #        terra::as.points(terra::ext(x), crs=terra::crs(x)),
  #        epsg4326)
  #  )

  if (project) {
    # if we should project the data
    x <- projectRasterForLeaflet(x, method)
    if (method == "bilinear") {
      has_colors <- FALSE
    }
  }

  if (!is.function(colors)) {
    if (method == "near" || has_colors) {
      # 'factors'
      domain <- NULL
      if (has_colors) {
        colors <- rgb(
          ctab[, 2],
          ctab[, 3],
          ctab[, 4],
          ctab[, 5],
          maxColorValue = 255
        )
        domain <- ctab[, 1]
      }
      colors <- colorFactor(
        colors,
        domain = domain,
        na.color = "#00000000",
        alpha = TRUE
      )
    } else {
      # 'numeric'
      colors <- colorNumeric(
        colors,
        domain = NULL,
        na.color = "#00000000",
        alpha = TRUE
      )
    }
  }

  tileData <- terra::values(x) %>%
    as.vector() %>%
    colors() %>%
    col2rgb(alpha = TRUE) %>%
    as.raw()
  dim(tileData) <- c(4, ncol(x), nrow(x))
  pngData <- png::writePNG(tileData)
  if (length(pngData) > maxBytes) {
    stop(
      "Raster image too large; ",
      length(pngData),
      " bytes is greater than maximum ",
      maxBytes,
      " bytes"
    )
  }
  uri <- xfun::base64_uri(pngData, "image/png")

  latlng <- list(
    list(terra::ymax(bounds), terra::xmin(bounds)),
    list(terra::ymin(bounds), terra::xmax(bounds))
  )

  invokeMethod(
    map,
    data,
    "addRasterImage",
    uri,
    latlng,
    layerId,
    group,
    options
  ) %>%
    expandLimits(
      c(terra::ymin(bounds), terra::ymax(bounds)),
      c(terra::xmin(bounds), terra::xmax(bounds))
    )
}`

const rtdal003809Source0017 = `projectRasterForLeaflet <- function(x, method) {
  if (inherits(x, "SpatRaster")) {
    if (method == "ngb") {
      method = "near"
    }
    terra::project(
      x,
      y = epsg3857,
      method = method
    )
  } else {
    raster_is_factor <- raster::is.factor(x)
    projected <- raster::projectRaster(
      x,
      raster::projectExtent(x, crs = sp::CRS(epsg3857)),
      method = method
    )
    # if data is factor data, make the result factors as well.
    # only meaningful if ngb was used
    if ((raster_is_factor) && (method == "ngb")) {
      raster::as.factor(projected)
    } else {
      projected
    }
  }
}`

