const rtdal003809Source0030 = `safeLabel <- function(label, data) {
  if (is.null(label)) {
    return(label)
  }

  label <- evalFormula(label, data)
  if (
    !(
      inherits(label, "html") ||
        sum(sapply(label, function(x) {
          !inherits(x, "html")
        })) ==
          0 # nolint
    )
  ) {
    label <- htmltools::htmlEscape(label)
  }
  label
}`

const rtdal003809Source0031 = `labelOptions <- function(
  interactive = FALSE,
  clickable = NULL,
  noHide = NULL,
  permanent = FALSE,
  className = "",
  direction = "auto",
  offset = c(0, 0),
  opacity = 1,
  textsize = "10px",
  textOnly = FALSE,
  style = NULL,
  zoomAnimation = NULL,
  sticky = TRUE,
  ...
) {
  # use old (Leaflet 0.7.x) clickable if provided
  if (!is.null(clickable) && interactive != clickable) {
    interactive <- clickable
  }
  # use old noHide if provided
  if (!is.null(noHide) && permanent != noHide) {
    permanent <- noHide
  }
  if (!missing(zoomAnimation)) {
    zoomAnimationWarning()
  }

  filterNULL(list(
    interactive = interactive,
    permanent = permanent,
    direction = direction,
    opacity = opacity,
    offset = offset,
    textsize = textsize,
    textOnly = textOnly,
    style = style,
    className = className,
    sticky = sticky,
    ...
  ))
}`

