const rtdal003815Source0001 = `setView <- function(map, lng, lat, zoom, options = list()) {
  view <- evalFormula(list(c(lat, lng), zoom, options))

  dispatch(map,
    "setView",
    leaflet = {
      changeView(map, setView = view)
    },
    leaflet_proxy = {
      invokeRemote(map, "setView", view)
      map
    }
  )
}`

