const rtdal003822Source0008 = `awesomeIconList <- function(...) {
  res <- structure(
    list(...),
    class = "leaflet_awesome_icon_set"
  )
  cls <- unlist(lapply(res, inherits, "leaflet_awesome_icon"))
  if (any(!cls))
    stop("Arguments passed to awesomeIconList() must be icon objects returned from makeAwesomeIcon()") # nolint
  res
}`

const rtdal003822Source0010 = "awesomeIconSetToAwesomeIcons <- function(x) {\n  # c(\"icon\", \"library\", ...)\n  cols <- names(formals(makeAwesomeIcon))\n  # list(icon = \"icon\", library = \"library\", ...)\n  cols <- structure(as.list(cols), names = cols)\n\n  # Construct an equivalent output to awesomeIcons().\n  filterNULL(lapply(cols, function(col) {\n    # Pluck the `col` member off of each item in awesomeIconObjs and put them in an\n    # unnamed list (or vector if possible).\n    colVals <- unname(sapply(x, `[[`, col))\n\n    # If this is the common case where there's lots of values but they're all\n    # actually the same exact thing, then just return one value; this will be\n    # much cheaper to send to the client, and we'll do recycling on the client\n    # side anyway.\n    if (length(unique(colVals)) == 1) {\n      return(colVals[[1]])\n    } else {\n      return(colVals)\n    }\n  }))\n}"

const rtdal003822Source0013 = `verifyIconLibrary <- function(library) {
  bad <- library[!(library %in% c("glyphicon", "fa", "ion"))]
  if (length(bad) > 0) {
    stop("Invalid icon library names: ", paste(unique(bad), collapse = ", "))
  }
}`

const rtdal003822Source0014 = `addAwesomeMarkers <- function(
  map, lng = NULL, lat = NULL, layerId = NULL, group = NULL,
  icon = NULL,
  popup = NULL,
  popupOptions = NULL,
  label = NULL,
  labelOptions = NULL,
  options = markerOptions(),
  clusterOptions = NULL,
  clusterId = NULL,
  data = getMapData(map)
) {
  if (missing(labelOptions)) labelOptions <- labelOptions()
  map$dependencies <- c(map$dependencies, leafletAwesomeMarkersDependencies())

  if (!is.null(icon)) {
    # If formulas are present, they must be evaluated first so we can pack the
    # resulting values
    icon <- evalFormula(list(icon), data)[[1]]

    if (inherits(icon, "leaflet_awesome_icon_set")) {
      icon <- awesomeIconSetToAwesomeIcons(icon)
    }
    icon <- filterNULL(icon)
    verifyIconLibrary(icon$library)
    lapply(unique(icon$library), function(lib) {
      libFunc <- switch(lib,
        glyphicon = addBootstrap,
        fa = addFontAwesome,
        ion = addIonIcon,
        default = stop("Unknown icon library \"", lib, "\"")
      )
      map <<- libFunc(map)
    })
    icon$prefix <- icon$library
    icon$library <- NULL
  }

  if (!is.null(clusterOptions))
    map$dependencies <- c(map$dependencies, markerClusterDependencies())

  pts <- derivePoints(data, lng, lat, missing(lng), missing(lat), "addAwesomeMarkers")
  invokeMethod(
    map, data, "addAwesomeMarkers", pts$lat, pts$lng, icon, layerId,
    group, options, popup, popupOptions,
    clusterOptions, clusterId, safeLabel(label, data), labelOptions,
    getCrosstalkOptions(data)
  ) %>% expandLimits(pts$lat, pts$lng)
}`

