const rtdal003828Source0001 = `leafletProviderDependencies <- function() {
  list(
    get_providers_html_dependency(),
    htmltools::htmlDependency(
      "leaflet-providers-plugin",
      get_package_version("leaflet"),
      "htmlwidgets/plugins/leaflet-providers-plugin",
      package = "leaflet",
      script = "leaflet-providers-plugin.js"
    )
  )
}`

const rtdal003828Source0002 = "addProviderTiles <- function(\n  map,\n  provider,\n  layerId = NULL,\n  group = NULL,\n  options = providerTileOptions(),\n  check = TRUE\n) {\n  if (check) {\n    loaded_providers <- leaflet.providers::providers_loaded()\n    if (!provider %in% names(loaded_providers$providers)) {\n      stop(\n        \"Unknown tile provider '\",\n        provider,\n        \"'; either use a known provider or pass `check = FALSE` to `addProviderTiles()`\"\n      )\n    }\n  }\n  map$dependencies <- c(map$dependencies, leafletProviderDependencies())\n  invokeMethod(map, getMapData(map), \"addProviderTiles\",\n    provider, layerId, group, options)\n}"

const rtdal003828Source0003 = `providerTileOptions <- function(errorTileUrl = "", noWrap = FALSE,
  opacity = NULL, zIndex = NULL,
  updateWhenIdle = NULL, detectRetina = FALSE, ...
) {
  opts <- filterNULL(list(
    errorTileUrl = errorTileUrl, noWrap = noWrap,
    opacity = opacity,  zIndex = zIndex,
    updateWhenIdle = updateWhenIdle, detectRetina = detectRetina,
    ...))
  opts
}`

const rtdal003828Source0012 = `create_temp_providers_html_dependency <- function() {
  # for compatibility with older versions of leaflet.providers
  tmpfile <- file.path(tempdir(), paste0("leaflet-providers_", providers.version_num, ".js"))

  if (!file.exists(tmpfile)) {
    src <- providers.src
    writeLines(src, tmpfile)
  }

  htmltools::htmlDependency(
    "leaflet-providers",
    providers.version_num,
    src = dirname(tmpfile),
    script = basename(tmpfile),
    all_files = FALSE
  )
}`

