const rtdal003835Source0003 = `invokeMethod <- function(map, data, method, ...) {
  if (crosstalk::is.SharedData(data)) {
    map$dependencies <- c(map$dependencies, crosstalk::crosstalkLibs())
    data <- data$data()
  } else {
    NULL
  }

  args <- evalFormula(list(...), data)

  dispatch(map,
    method,
    leaflet = {
      x <- map$x$calls
      if (is.null(x)) x <- list()
      n <- length(x)
      x[[n + 1]] <- list(method = method, args = args)
      map$x$calls <- x
      map
    },
    leaflet_proxy = {
      invokeRemote(map, method, args)
      map
    }
  )
}`

const rtdal003835Source0004 = "leafletProxy <- function(mapId, session = shiny::getDefaultReactiveDomain(),\n  data = NULL, deferUntilFlush = TRUE) {\n\n  if (is.null(session)) {\n    stop(\"leafletProxy must be called from the server function of a Shiny app\")\n  }\n\n  # If this is a new enough version of Shiny that it supports modules, and\n  # we're in a module (nzchar(session$ns(NULL))), and the mapId doesn't begin\n  # with the current namespace, then add the namespace.\n  #\n  # We could also have unconditionally done `mapId <- session$ns(mapId)`, but\n  # older versions of Leaflet would have broken unless the user did session$ns\n  # themselves, and we hate to break their code unnecessarily.\n  #\n  # This won't be necessary in future versions of Shiny, as session$ns (and\n  # other forms of ns()) will be smart enough to only namespace un-namespaced\n  # IDs.\n  if (\n    !is.null(session$ns) &&\n    nzchar(session$ns(NULL)) &&\n    substring(mapId, 1, nchar(session$ns(\"\"))) != session$ns(\"\")\n  ) {\n    mapId <- session$ns(mapId)\n  }\n\n  structure(\n    list(\n      session = session,\n      id = mapId,\n      x = structure(\n        list(),\n        leafletData = data\n      ),\n      deferUntilFlush = deferUntilFlush,\n      dependencies = NULL\n    ),\n    class = \"leaflet_proxy\"\n  )\n}"

const rtdal003835Source0006 = `invokeRemote <- function(map, method, args = list()) {
  if (!inherits(map, "leaflet_proxy"))
    stop("Invalid map parameter; map proxy object was expected")

  deps <- htmltools::resolveDependencies(map$dependencies)

  msg <- list(
    id = map$id,
    calls = list(
      list(
        dependencies = lapply(deps, shiny::createWebDependency),
        method = method,
        args = args,
        evals = htmlwidgets::JSEvals(args)
      )
    )
  )

  sess <- map$session
  if (map$deferUntilFlush) {

    # See comment on sessionFlushQueue.

    if (is.null(sessionFlushQueue[[sess$token]])) {
      # If the current session doesn't have an entry in the sessionFlushQueue,
      # initialize it with a blank list.
      sessionFlushQueue[[sess$token]] <- list()

      # If the session ends before the next onFlushed call, remove the entry
      # for this session from the sessionFlushQueue.
      endedUnreg <- sess$onSessionEnded(function() {
        rm(list = sess$token, envir = sessionFlushQueue)
      })

      # On the next flush, pass all the messages to the client, and remove the
      # entry from sessionFlushQueue.
      sess$onFlushed(function() {
        on.exit(rm(list = sess$token, envir = sessionFlushQueue), add = TRUE)
        endedUnreg()
        for (msg in sessionFlushQueue[[sess$token]]) {
          sess$sendCustomMessage("leaflet-calls", msg)
        }
      }, once = TRUE) # nolint
    }

    # Append the current value to the apporpriate sessionFlushQueue entry,
    # which is now guaranteed to exist.
    sessionFlushQueue[[sess$token]] <- c(sessionFlushQueue[[sess$token]], list(msg))

  } else {
    sess$sendCustomMessage("leaflet-calls", msg)
  }
  map
}`

